run_ct16.ps1.content:
param([Parameter(ValueFromRemainingArguments=$true)][string[]]$TrialArguments)
$ErrorActionPreference = 'Stop'
$ct16Container = (docker inspect caliburn-q019-postgres | ConvertFrom-Json)[0]
if ($LASTEXITCODE -ne 0 -or $ct16Container.State.Status -ne 'running') { throw 'Dedicated test database is not running' }
$ct16Settings = @{}
foreach ($ct16Entry in $ct16Container.Config.Env) {
    $ct16Pair = $ct16Entry.Split('=', 2)
    $ct16Settings[$ct16Pair[0]] = $ct16Pair[1]
}
if ($ct16Settings.POSTGRES_DB -ne 'q019_agent_test' -or $ct16Settings.POSTGRES_USER -ne 'q019') { throw 'Unexpected database identity' }
if ($ct16Container.NetworkSettings.Ports.'5432/tcp'[0].HostPort -ne '55433') { throw 'Unexpected port' }
$env:Q019_TEST_DATABASE_URL = 'postgresql://q019:' + [uri]::EscapeDataString($ct16Settings.POSTGRES_PASSWORD) + '@127.0.0.1:55433/q019_agent_test?connect_timeout=5'
$env:PYTHONUTF8 = '1'
$env:PYTHONPATH = 'src'
try {
    & .venv/Scripts/python.exe .test-tmp/ct16_run.py @TrialArguments
    $ct16Exit = $LASTEXITCODE
} finally {
    Remove-Item Env:Q019_TEST_DATABASE_URL -ErrorAction SilentlyContinue
    $ct16Settings.Clear()
}
exit $ct16Exit
